beforeExample:
package com.example;

import org.eclipse.core.runtime.Platform;
import org.eclipse.core.runtime.ILog;
import org.osgi.framework.Bundle;
import org.osgi.framework.FrameworkUtil;

public class MyClass {
    public void logSomething(Class<?> clazz) {
        Bundle bundle = FrameworkUtil.getBundle(clazz);
        // This call will be replaced
        ILog log = Platform.getLog(bundle);
        log.info("Hello from " + clazz.getName());
    }

    public void anotherMethod(Bundle someBundle) {
        ILog log = Platform.getLog(someBundle);
        log.warn("Another log message.");
    }
}

afterExample:
package com.example;

import org.eclipse.core.runtime.ILog;
import org.osgi.framework.Bundle;
import org.osgi.framework.FrameworkUtil;

public class MyClass {
    public void logSomething(Class<?> clazz) {
        Bundle bundle = FrameworkUtil.getBundle(clazz);
        // This call has been replaced with the new ILog.of method
        ILog log = ILog.of(bundle);
        log.info("Hello from " + clazz.getName());
    }

    public void anotherMethod(Bundle someBundle) {
        ILog log = ILog.of(someBundle);
        log.warn("Another log message.");
    }
}

