package com.example;

import org.eclipse.core.runtime.Platform;
import org.eclipse.core.runtime.ILog;
import org.osgi.framework.Bundle;
import org.osgi.framework.FrameworkUtil;

public class MyOtherClass {
    public void logSomethingElse(Class<?> clazz) {
        // This method signature (getLog(Class<?>)) should not match the rule
        ILog log1 = Platform.getLog(clazz);
        log1.warn("Using Platform.getLog(Class<?>)");

        // This is a different new API and should not match
        ILog log2 = ILog.get();
        log2.error("Using ILog.get()");

        // This is the new API, but with Class<?> param, so it should not match this rule
        ILog log3 = ILog.of(clazz);
        log3.info("Using ILog.of(Class)");
    }
}
